package com.elitedarkkaiser.nubialy;
import android.view.*;import android.widget.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class SettingsHomeMountTest {
 @Test public void weightedNativeSlotSurvivesNavigationAndRestore(){var c=RuntimeEnvironment.getApplication();LinearLayout parent=new LinearLayout(c);parent.setOrientation(1);TextView header=new TextView(c);header.setText("Settings");parent.addView(header,new LinearLayout.LayoutParams(-1,60));View list=new View(c);var params=new LinearLayout.LayoutParams(-1,0,1);parent.addView(list,params);for(int i=0;i<5;i++){View custom=new View(c);SettingsHomeMount mount=new SettingsHomeMount(list);mount.install(custom);measure(parent);assertTrue(mount.mounted());assertEquals(View.INVISIBLE,list.getVisibility());assertTrue(custom.getHeight()>600);assertEquals(list.getHeight(),custom.getHeight());((ViewGroup)custom.getParent()).removeView(custom);assertFalse(mount.mounted());mount.restore();assertEquals(View.VISIBLE,list.getVisibility());assertSame(parent,list.getParent());assertSame(params,list.getLayoutParams());assertSame(list,parent.getChildAt(1));assertEquals(2,parent.getChildCount());mount.restore();assertEquals(2,parent.getChildCount());}}
 @Test public void detachedHostCannotStrandNativeList(){var c=RuntimeEnvironment.getApplication();FrameLayout parent=new FrameLayout(c);View list=new View(c);parent.addView(list,new FrameLayout.LayoutParams(-1,-1));SettingsHomeMount mount=new SettingsHomeMount(list);mount.install(new View(c));View host=(View)list.getParent();parent.removeView(host);mount.restore();assertSame(parent,list.getParent());assertEquals(View.VISIBLE,list.getVisibility());assertEquals(1,parent.getChildCount());}
 @Test public void replacingNativeListRestoresTheOldListIndependently(){var c=RuntimeEnvironment.getApplication();FrameLayout first=new FrameLayout(c),second=new FrameLayout(c);View oldList=new View(c),newList=new View(c);first.addView(oldList);second.addView(newList);var old=new SettingsHomeMount(oldList);old.install(new View(c));old.restore();var replacement=new SettingsHomeMount(newList);replacement.install(new View(c));assertEquals(View.VISIBLE,oldList.getVisibility());replacement.restore();assertSame(second,newList.getParent());assertEquals(View.VISIBLE,newList.getVisibility());}
 @Test public void replacedNativeListDoesNotResurrectTheObsoleteList(){var c=RuntimeEnvironment.getApplication();FrameLayout parent=new FrameLayout(c);View old=new View(c),replacement=new View(c);parent.addView(old);var mount=new SettingsHomeMount(old);mount.install(new View(c));parent.addView(replacement);mount.discard();assertNull(old.getParent());assertEquals(1,parent.getChildCount());assertSame(replacement,parent.getChildAt(0));assertEquals(View.VISIBLE,replacement.getVisibility());}
 private void measure(View v){v.measure(View.MeasureSpec.makeMeasureSpec(440,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.EXACTLY));v.layout(0,0,440,900);}
}
